-- Disposable test baseline matching the audited pre-migration ORVIO schema.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
grant usage on schema auth,public to anon,authenticated;
create table auth.users(id uuid primary key default gen_random_uuid(),raw_user_meta_data jsonb default '{}'::jsonb);
create table public.profiles(id uuid primary key references auth.users on delete cascade, full_name text, role text default 'participant' check(role in ('participant','organizer','admin')),created_at timestamptz default now(),updated_at timestamptz default now());
create table public.events(id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles on delete cascade,title text not null,description text,venue text not null,banner_url text,max_participants integer,status text not null default 'pending' check(status in ('pending','approved','rejected','completed','cancelled')),created_at timestamptz default now(),updated_at timestamptz default now(),event_datetime timestamptz);
create table public.registrations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,user_id uuid not null references public.profiles on delete cascade,registered_at timestamptz default now(),constraint registrations_event_id_user_id_key unique(event_id,user_id),constraint registrations_event_user_unique unique(event_id,user_id));
create function public.is_admin() returns boolean language sql stable security definer set search_path='public' as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create function public.handle_new_user() returns trigger language plpgsql security definer as $$begin insert into public.profiles(id,full_name,role) values(new.id,new.raw_user_meta_data->>'full_name','participant'); return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;
alter table public.events enable row level security;
alter table public.registrations enable row level security;
grant all on all tables in schema public to anon,authenticated,service_role;
create policy "Users can insert own profile" on public.profiles for insert with check(auth.uid()=id);
create policy "Users can update own profile" on public.profiles for update using(auth.uid()=id);
create policy "Users can view own profile" on public.profiles for select using(auth.uid()=id);
create policy admin_select_profiles on public.profiles for select to authenticated using(is_admin());
create policy admin_update_profiles on public.profiles for update to authenticated using(is_admin()) with check(is_admin());
create policy "Users can create events" on public.events for insert to authenticated with check(auth.uid()=created_by);
create policy "Anyone can view approved events" on public.events for select using(status='approved' or created_by=auth.uid());
create policy "Users update own pending events" on public.events for update to authenticated using(created_by=auth.uid() and status='pending') with check(created_by=auth.uid() and status='pending');
create policy "Users can delete their own pending events" on public.events for delete to authenticated using(created_by=auth.uid() and status='pending');
create policy admin_select_events on public.events for select to authenticated using(is_admin());
create policy admin_update_events on public.events for update to authenticated using(is_admin()) with check(is_admin());
create policy admin_delete_events on public.events for delete to authenticated using(is_admin());
create policy "Users register" on public.registrations for insert to authenticated with check(auth.uid()=user_id);
create policy "Users view registrations" on public.registrations for select to authenticated using(auth.uid()=user_id);
create policy admin_delete_registrations on public.registrations for delete to authenticated using(is_admin());
